WITH base AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, CASE WHEN device_code IN ('DV-02', 'DV-01') THEN 'Group A' ELSE 'Other' END AS device_code_group FROM device_readings WHERE reading_ts > TO_TIMESTAMP('2025-09-01 07:00:00')) SELECT CASE WHEN pressure >= 1029 THEN 'HIGH' ELSE 'LOW' END AS pressure_tier, ROUND(AVG(pressure), 2) AS avg_pressure, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes FROM base GROUP BY CASE WHEN pressure >= 1029 THEN 'HIGH' ELSE 'LOW' END ORDER BY span_minutes;
